```c
#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int stack[100005];
    int top = 0;
    long long sum = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        if (x == 0) {
            if (top > 0) {
                sum -= stack[--top];
            }
        } else {
            stack[top++] = x;
            sum += x;
        }
    }

    printf("%lld\n", sum);
    return 0;
}
```

